	if params.CreatedAtNeq != nil {
		conds = append(conds, sq.NotEq{"created_at": *params.CreatedAtNeq})
	}
	if params.CreatedAtIn != nil {
		conds = append(conds, sq.Eq{"created_at": params.CreatedAtIn})
	}
	if params.CreatedAtNotIn != nil {
		conds = append(conds, sq.NotEq{"created_at": params.CreatedAtNotIn})
	}
	if params.CreatedAtGt != nil {
		conds = append(conds, sq.Gt{"created_at": *params.CreatedAtGt})
	}
	if params.CreatedAtGte != nil {
		conds = append(conds, sq.GtOrEq{"created_at": *params.CreatedAtGte})
	}
	if params.CreatedAtLt != nil {
		conds = append(conds, sq.Lt{"created_at": *params.CreatedAtLt})
	}
	if params.CreatedAtLte != nil {
		conds = append(conds, sq.LtOrEq{"created_at": *params.CreatedAtLte})
	}
	if params.UpdatedBy != nil {
		conds = append(conds, sq.Eq{"updated_by": *params.UpdatedBy})
	}
	if params.UpdatedByNeq != nil {
		conds = append(conds, sq.NotEq{"updated_by": *params.UpdatedByNeq})
	}
	if params.UpdatedByIn != nil {
		conds = append(conds, sq.Eq{"updated_by": params.UpdatedByIn})
	}
	if params.UpdatedByNotIn != nil {
		conds = append(conds, sq.NotEq{"updated_by": params.UpdatedByNotIn})
	}
	if params.UpdatedAtGt != nil {
		conds = append(conds, sq.Gt{"updated_at": *params.UpdatedAtGt})
	}
	if params.UpdatedAtGte != nil {
		conds = append(conds, sq.GtOrEq{"updated_at": *params.UpdatedAtGte})
	}
	if params.UpdatedAtLt != nil {
		conds = append(conds, sq.Lt{"updated_at": *params.UpdatedAtLt})
	}
	if params.UpdatedAtLte != nil {
		conds = append(conds, sq.LtOrEq{"updated_at": *params.UpdatedAtLte})
	}
	return conds
