// sys_sessionCursorValues 提取用于构造 nextCursor 的排序列值,顺序与有效排序一致。
//
// 参数:
//   - row: 查询结果中的一行模型。
//   - seq: 排序列及方向,顺序与游标值顺序一致。
//
// 返回值:
//   - []any: 与 seq 一一对应的列值切片。
func sys_sessionCursorValues(row SysSession, seq []dynq.SortField) []any {
	vals := make([]any, len(seq))
	for i, sf := range seq {
		switch sf.Key {
		case "id":
			vals[i] = row.ID
		case "status":
			vals[i] = row.Status
		case "expiresAt":
			vals[i] = row.ExpiresAt
		case "lastActivityAt":
			vals[i] = row.LastActivityAt
		case "createdAt":
			vals[i] = row.CreatedAt
		case "updatedAt":
			vals[i] = row.UpdatedAt
		default:
			vals[i] = nil
		}
	}
	return vals
}

// ListSysSession 按 params 的过滤、排序、投影与分页条件查询列表页。
// 返回本页行、是否还有下一页与续翻游标;total 由 CountSysSession 单独计算
// (非强一致快照)。生成代码为纯函数,不持有连接状态。
// 未查询列在结果中留零值(动态投影固有语义),需区分时按请求 fields 做 DTO 化。
//
// 参数:
//   - ctx:    查询上下文。
//   - db:     数据库连接,满足 DBTX 接口即可。
//   - params: typed 查询参数,可由 ParseSysSessionQuery 产出或直接构造。
//   - opts:   运行期能力收窄选项;禁用目标不在 registry 时返回错误。
//
// 返回值:
//   - dynq.Result[SysSession]: 本页行、是否还有下一页与续翻游标。
//   - error:              查询或校验失败时的错误。
func ListSysSession(ctx context.Context, db DBTX, params ListSysSessionParams, opts ...dynq.QueryOption) (dynq.Result[SysSession], error) {
	cfg, err := dynq.NewQueryConfig(sys_sessionRegistry, opts...)
	if err != nil {
		return dynq.Result[SysSession]{}, err
	}
	if err := validateSysSessionParams(params, cfg); err != nil {
		return dynq.Result[SysSession]{}, err
	}
	limit, err := dynq.CheckPagination(sys_sessionRegistry, params.Limit, params.Offset, params.After)
	if err != nil {
		return dynq.Result[SysSession]{}, err
	}
	// 解析有效排序:未指定排序时回落表级 @default_sort。
	seq, err := dynq.ResolveSort(sys_sessionRegistry, cfg, params.OrderBy)
	if err != nil {
		return dynq.Result[SysSession]{}, err
	}
	fp := dynq.CursorFingerprint(sys_sessionRegistry.Resource, seq)
	// 计算 SELECT 列:投影列并集排序列(排序所需列始终参与查询)。
	cols := dynq.SelectColumns(sys_sessionRegistry, params.SelectFields, seq)
	b := sq.Select(cols...).From("sys_session").PlaceholderFormat(sq.Dollar).Where(sq.And(buildSysSessionWhere(params))).
		OrderBy(dynq.OrderBySQL(seq)).Limit(uint64(limit) + 1)
	// After 非 nil 时为游标模式:解码并校验游标,从该位置继续读取。
	if params.After != nil {
		vals, err := dynq.DecodeCursor(*params.After, fp, seq)
		if err != nil {
			return dynq.Result[SysSession]{}, err
		}
		seek, err := dynq.SeekPredicate(seq, vals)
		if err != nil {
			return dynq.Result[SysSession]{}, err
		}
		b = b.Where(seek)
	}
	if params.Offset > 0 {
		b = b.Offset(uint64(params.Offset))
	}
	query, args, err := b.ToSql()
	if err != nil {
		return dynq.Result[SysSession]{}, err
	}
	rows, err := db.Query(ctx, query, args...)
	if err != nil {
		return dynq.Result[SysSession]{}, err
	}
	items, err := pgx.CollectRows(rows, pgx.RowToStructByNameLax[SysSession])
	if err != nil {
		return dynq.Result[SysSession]{}, err
	}
	// 以 LIMIT n+1 探测是否还有下一页,并构造 nextCursor。
	hasMore := len(items) > int(limit)
	if hasMore {
		items = items[:limit]
	}
	var next string
	if hasMore {
		next, err = dynq.EncodeCursor(fp, seq, sys_sessionCursorValues(items[len(items)-1], seq))
		if err != nil {
			return dynq.Result[SysSession]{}, err
		}
	}
	return dynq.Result[SysSession]{Items: items, HasMore: hasMore, NextCursor: next}, nil
}

// CountSysSession 统计满足过滤条件的行数,与分页模式和游标位置无关;
// 忽略投影、排序与游标。
//
// 参数:
//   - ctx:    查询上下文。
//   - db:     数据库连接,满足 DBTX 接口即可。
//   - params: typed 查询参数,与 ListSysSession 使用同一份形态复核。
//   - opts:   运行期能力收窄选项。
//
// 返回值:
//   - int64: 满足过滤条件的行数。
//   - error: 查询或校验失败时返回错误。
func CountSysSession(ctx context.Context, db DBTX, params ListSysSessionParams, opts ...dynq.QueryOption) (int64, error) {
	cfg, err := dynq.NewQueryConfig(sys_sessionRegistry, opts...)
	if err != nil {
		return 0, err
	}
	if err := validateSysSessionParams(params, cfg); err != nil {
		return 0, err
	}
	if _, err := dynq.CheckPagination(sys_sessionRegistry, params.Limit, params.Offset, params.After); err != nil {
		return 0, err
	}
	query, args, err := sq.Select("COUNT(*)").From("sys_session").PlaceholderFormat(sq.Dollar).Where(sq.And(buildSysSessionWhere(params))).ToSql()
	if err != nil {
		return 0, err
	}
	var total int64
	if err := db.QueryRow(ctx, query, args...).Scan(&total); err != nil {
		return 0, err
	}
	return total, nil
}

// SysSessionQuerySchema 是前端契约出口:返回经 opts 减法投影后的有效能力全集,
// 前端据此渲染查询组件。Schema 是(生成期元数据, opts)的确定性纯函数,
// 同一 opts 产出字节级相同结果,内容 hash 可作 ETag;被禁用字段不出现于 schema。
//
// 参数:
//   - opts: 运行期能力收窄选项,须与 Parse/List/Count 使用同一份 opts。
//
// 返回值:
//   - dynq.ResourceSchema: 前端渲染所需的能力描述(字段、操作符、排序、分页配置)。
func SysSessionQuerySchema(opts ...dynq.QueryOption) dynq.ResourceSchema {
	cfg, err := dynq.NewQueryConfig(sys_sessionRegistry, opts...)
	if err != nil {
		// 禁用目标不在 registry 属于编程错误。Parse/List/Count/Schema 四点同参纪律
		// 下,此处 panic 显式暴露;静默吞错会掩盖权限收窄失效。
		panic(err)
	}
	return dynq.BuildSchema(sys_sessionRegistry, cfg)
}
